import { scoreWho5, buildHandoff, transitionReferral, summarizeOutcomes } from './domain.mjs';

const paths={overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',check:'<path d="M9 3h6v4H9z"/><path d="M8 5H5v16h14V5h-3M8 13l3 3 5-6"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 6-5 2 2-5z"/>',journey:'<circle cx="6" cy="6" r="2"/><circle cx="18" cy="18" r="2"/><path d="M8 6h7a4 4 0 0 1 0 8H9a4 4 0 0 0-1 8M16 18h-5"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9S4 17 4 12V6z"/><path d="m8 12 3 3 5-6"/>',team:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6M17 14a5 5 0 0 1 4 5v2"/>',chart:'<path d="M4 3v18h17M8 16v-5M13 16V7M18 16v-9"/>',leaf:'<path d="M19 3C7 3 2 9 5 15c3 5 12 5 14-12ZM5 20 15 9M9 15v-5M9 15h5"/>',arrow:'<path d="M4 12h16m-5-5 5 5-5 5"/>',external:'<path d="M14 3h7v7M21 3 10 14M10 4H4v16h16v-6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 11h18"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4M12 14v3"/>',heart:'<path d="M20 5c-3-3-7-1-8 1-1-2-5-4-8-1s-1 7 1 9l7 7 7-7c2-2 4-6 1-9Z"/>',life:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="4"/><path d="m5.5 5.5 3.7 3.7M14.8 14.8l3.7 3.7M18.5 5.5l-3.7 3.7M9.2 14.8l-3.7 3.7"/>',tick:'<path d="m5 12 4 4L19 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',phone:'<path d="m7 3 3 5-3 3c2 3 3 4 6 6l3-3 5 3-2 4C10 22 2 14 3 5z"/>',home:'<path d="m3 10 9-7 9 7M5 9v12h14V9M10 21v-7h4v7"/>',video:'<rect x="3" y="5" width="12" height="14" rx="2"/><path d="m15 10 6-4v12l-6-4"/>',book:'<path d="M12 5c-4-3-9-2-9-2v16s5-1 9 2c4-3 9-2 9-2V3s-5-1-9 2Zm0 0v16"/>',trash:'<path d="M4 7h16M9 3h6l1 4M6 7l1 14h10l1-14M10 10v7M14 10v7"/>',refresh:'<path d="M20 8a9 9 0 1 0 0 8M20 3v5h-5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.info}</svg>`;
const navItems=[['overview','overview','Overview'],['check-in','check','Check-in'],['support','compass','Find support'],['journey','journey','Care journey'],['privacy','shield','Privacy & consent'],['care-team','team','Care team'],['outcomes','chart','Outcomes']];
const main=document.querySelector('#main');
const modalRoot=document.querySelector('#modal-root');
const questions=['I have felt cheerful and in good spirits','I have felt calm and relaxed','I have felt active and vigorous','I woke up feeling fresh and rested','My daily life has been filled with things that interest me'];
const responses=['At no time','Some of the time','Less than half of the time','More than half of the time','Most of the time','All of the time'];
const state={page:'overview',step:0,answers:Array(5).fill(null),assessment:null,history:[],consent:{history:false,score:false,access:false,physical:false},physical:[],preferences:{type:'all',language:'English',format:'any'},referrals:[],selectedReferral:null,modal:null,share:{score:false,access:false,physical:false},selectedService:'sakina',urgentSelfDisclosure:false};
const services=[{id:'primary',name:'SEHA primary care',type:'primary',label:'Primary care',format:'in-person',languages:['English','Arabic'],icon:'home',description:'Start a conversation about your mental and physical wellbeing with a primary-care professional.',tags:['Whole-person care','In person'],url:'https://www.seha.ae',recipient:'SEHA primary-care team (simulated)'},{id:'sakina',name:'Sakina',type:'specialist',label:'Mental health · Tele / outpatient',format:'both',languages:['English','Arabic'],icon:'video',description:'Explore SEHA’s mental health services and discuss the right next step with a licensed professional.',tags:['Mental health','Tele / outpatient'],url:'https://sakina.seha.ae',recipient:'Sakina care team (simulated)'},{id:'self-help',name:'Everyday support',type:'self-help',label:'Self-help · WHO resources',format:'remote',languages:['English','Arabic'],icon:'book',description:'Explore WHO’s practical guide to managing stress, at your own pace and alongside professional support.',tags:['Self-guided','No referral'],url:'https://www.who.int/publications/i/item/9789240003927',recipient:null}];
let toastTimer;let priorFocus;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,action,style='primary',extra='')=>`<button class="btn btn-${style}" data-action="${action}" ${extra}>${label}</button>`;
const notice=(text,type='')=>`<div class="notice ${type}">${icon(type==='warning'?'life':'info')}<div>${text}</div></div>`;
const latestReferral=()=>state.referrals[state.referrals.length-1];
const statusLabel=status=>({sent:'Awaiting human review',accepted:'Accepted · simulated',declined:'Declined · simulated',rerouted:'Reroute requested',completed:'Contact completed · simulated',withdrawn:'Sharing withdrawn'}[status]||status);
const statusClass=status=>({sent:'warning',accepted:'success',declined:'warning',rerouted:'warning',completed:'success',withdrawn:'neutral'}[status]||'neutral');
const activeReferral=()=>state.referrals.find(r=>r.id===state.selectedReferral)||latestReferral();

document.querySelector('#primary-nav').innerHTML=navItems.map(([id,symbol,label])=>`<a href="#${id}" class="nav-item" data-page="${id}">${icon(symbol)}<span>${label}</span>${id==='care-team'?'<span class="nav-demo">SIM</span>':''}</a>`).join('');
document.querySelector('#privacy-icon').innerHTML=icon('shield');
document.querySelector('#urgent-icon').innerHTML=icon('life');
document.querySelector('.sidebar').insertAdjacentHTML('afterbegin','<span class="mobile-demo-label"><button data-action="urgent">I need help now ↗</button></span>');

function heading(title,description,eyebrow='YOUR WELLBEING, YOUR WAY',right='') {return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${right}</div>`;}
function render(){
  document.body.dataset.page=state.page;
  document.querySelector('#breadcrumb').textContent=navItems.find(x=>x[0]===state.page)?.[2]||'Overview';
  document.querySelectorAll('[data-page]').forEach(el=>{el.classList.toggle('active',el.dataset.page===state.page);if(el.dataset.page===state.page)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
  const pages={overview:overviewPage,'check-in':checkinPage,support:supportPage,journey:journeyPage,privacy:privacyPage,'care-team':careTeamPage,outcomes:outcomesPage};
  main.innerHTML=(pages[state.page]||overviewPage)();
}
function navigate(page){if(!navItems.some(n=>n[0]===page))page='overview';state.page=page;render();window.scrollTo({top:0,behavior:'instant'});}
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
function go(page){if(location.hash===`#${page}`)navigate(page);else location.hash=page;}

function overviewPage(){
  const score=state.assessment?.score??44;
  const referral=latestReferral();
  return `${heading('A little space for you.','Notice how you feel. Choose what happens next.','WELCOME TO SILA',`<div class="date-pill">${icon('calendar')} Your wellbeing, at your pace</div>`)}
  <div class="overview-grid">
    <section class="card hero-card"><div class="hero-copy"><div class="eyebrow">SMALL CHECK-INS. MEANINGFUL CONNECTIONS.</div><h2>How have you<br>been, really?</h2><p>A few moments to reflect on your wellbeing.<br>A clear, supported next step if you need one.</p><div class="button-row">${btn(`Start a check-in ${icon('arrow')}`,'start-checkin','lime')}<span class="hero-sub">5 questions · about 2 minutes</span></div></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="stem"></div><div class="petal"></div><div class="petal"></div><div class="petal"></div><div class="petal"></div><div class="orbit"></div></div></section>
    <section class="card trend-card" aria-label="Illustrative wellbeing trend"><div class="card-top"><div class="card-kicker">${icon('leaf')} WELLBEING SNAPSHOT</div><span class="badge neutral">${state.assessment?'This session':'SYNTHETIC'}</span></div><h2 class="trend-title">Your wellbeing, over time</h2><div class="trend-sub">${state.assessment?'Your latest WHO-5 check-in':'Illustrative WHO-5 scores · not your results'}</div><div class="score-row"><span class="score-big">${score}<small> / 100</small></span><span class="score-change">${state.assessment?'Your check-in':'Demo score'}</span></div><svg class="chart" viewBox="0 0 340 100" role="img" aria-label="Synthetic scores 32, 40, 36, 44 over four weeks"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#cde6a1" stop-opacity=".45"/><stop offset="1" stop-color="#eaf3db" stop-opacity=".1"/></linearGradient></defs><path d="M5 70H335M5 40H335M5 10H335" stroke="#edf1e7" stroke-dasharray="3 4"/><path d="M6 76C39 76 46 38 86 43S140 65 174 53 221 23 252 29 298 15 334 15V99H6Z" fill="url(#chart-fill)"/><path d="M6 76C39 76 46 38 86 43S140 65 174 53 221 23 252 29 298 15 334 15" fill="none" stroke="#9cbe69" stroke-width="2"/><circle cx="334" cy="15" r="4" fill="#759c4f" stroke="#fff" stroke-width="3"/></svg><div class="chart-labels"><span>6 weeks ago</span><span>4 weeks ago</span><span>2 weeks ago</span><span>Latest</span></div><div class="chart-note">A reflection tool, not a diagnosis. ${state.assessment?'Chart remains an illustration.':'Higher scores reflect greater reported wellbeing.'}</div></section>
  </div>
  <div class="section-heading"><h2>Your next step, made clear.</h2><span class="label">You are always in control</span></div>
  <div class="overview-bottom"><section class="card journey-card"><div class="card-top"><div class="round-icon">${icon('journey')}</div><span class="badge ${referral?statusClass(referral.status):''}">${referral?statusLabel(referral.status):'No handoff yet'}</span></div><h3>${referral?'A connection you can follow.':'Care should never feel like a maze.'}</h3><p>${referral?`Your ${esc(referral.serviceName)} handoff has a visible receipt. Every step here is simulated.`:'Choose trusted support, approve what you share, and see whether a human has responded.'}</p><div class="journey-steps"><div class="journey-step current"><span class="step-circle">${referral?'✓':'1'}</span> Choose support</div><div class="journey-step ${referral?'current':''}"><span class="step-circle">${referral?'✓':'2'}</span> You approve</div><div class="journey-step ${referral&&['accepted','completed'].includes(referral.status)?'current':''}"><span class="step-circle">3</span> Human responds</div></div><div class="mini-action"><span>${referral?'A visible receipt. A person at the next step.':'Every handoff begins with your permission.'}</span><button class="text-link" data-action="go-${referral?'journey':'support'}">${referral?'View care journey':'Explore support'} ${icon('arrow')}</button></div></section><section class="card support-card"><div class="card-kicker">${icon('compass')} THE RIGHT SUPPORT, FOR YOU</div><h3>You don’t have to<br>figure it out alone.</h3><p>From practical self-help to a conversation with a professional. Find your next step.</p><button class="text-link" data-action="go-support">Find trusted support ${icon('arrow')}</button><div class="support-decoration" aria-hidden="true">${icon('heart')}</div></section></div>
  <div class="principles"><span>${icon('shield')} Built around your trust</span><span>${icon('tick')} Your choice to check in</span><span>${icon('lock')} Share only what you choose</span><span>${icon('team')} Human decisions, always</span></div>`;
}

function checkinPage(){
  if(state.assessment&&state.step===5)return resultPage();
  const q=state.step;
  return `${heading('Let’s check in.','There are no right answers. Choose what feels closest to your experience.','A MOMENT FOR YOURSELF')}
  <div class="assessment-layout"><section class="card assessment-card"><div class="assessment-meta"><span>WHO-5 WELLBEING CHECK-IN</span><span>QUESTION ${q+1} OF 5</span></div><div class="progress-track"><span style="width:${(q+1)*20}%"></span></div><p class="question-prefix">Over the last two weeks…</p><h2 class="question-title" id="question-title">${questions[q]}.</h2><div class="response-grid" role="radiogroup" aria-labelledby="question-title">${[5,4,3,2,1,0].map(value=>`<button class="response-option ${state.answers[q]===value?'selected':''}" role="radio" aria-checked="${state.answers[q]===value}" data-action="answer" data-value="${value}"><span class="response-number">${value}</span>${responses[value]}<span class="radio-dot"></span></button>`).join('')}</div><div class="assessment-nav"><button class="text-button" data-action="previous-question" ${q===0?'disabled':''}>← Previous</button>${btn(q===4?`See my reflection ${icon('arrow')}`:`Continue ${icon('arrow')}`,'next-question','primary',state.answers[q]===null?'disabled':'')}</div></section><aside class="card info-card"><div class="round-icon">${icon('leaf')}</div><h3>A check-in, not a label.</h3><p>The WHO-5 helps you reflect on your wellbeing over the past two weeks. It does not diagnose a condition or assess emergency risk.</p><div class="info-divider"></div><ul><li>Participation is your choice.</li><li>Skip or leave whenever you wish.</li><li>Answers stay in this browser session.</li><li>SILA does not send check-in data to employers.</li></ul><div class="info-divider"></div><button class="text-link" data-action="urgent">Need support right now? ${icon('arrow')}</button></aside></div><div class="assessment-footer">WHO-5 wording and scoring: World Health Organization (2024). <a href="https://www.who.int/publications/m/item/WHO-UCN-MSD-MHE-2024.01" target="_blank" rel="noopener noreferrer">WHO-5 Well-Being Index</a> · CC BY-NC-SA 3.0 IGO. Instrument content is licensed separately from SILA’s code. This English demonstration is for adults 18+; no validated Arabic interface is claimed.</div>`;
}
function resultPage(){
  const a=state.assessment;
  return `${heading('A little more understanding.','Your result is a starting point for reflection. You decide what comes next.','YOUR CHECK-IN REFLECTION')}
  <div class="assessment-layout"><section class="card result-card"><div class="card-top"><div class="card-kicker">${icon('leaf')} WHO-5 WELLBEING INDEX</div><span class="badge">Current session</span></div><div class="result-score"><div class="score-ring" style="--score:${a.score}"><span>${a.score}<small>OUT OF 100</small></span></div><div><h2>${a.score<50?'It may help to talk.':'Take a moment to reflect.'}</h2><p>${a.score<50?'Your score suggests it would be helpful to discuss your wellbeing with a qualified professional.':'Your score reflects your reported wellbeing over the past two weeks. You can seek support at any score.'}</p></div></div>${notice('<strong>This is not a diagnosis.</strong> WHO-5 does not identify a mental health condition or determine suicide risk. A licensed professional can help you understand your needs.')}<p class="result-context">Scoring: ${a.rawScore} / 25 × 4 = ${a.score} / 100. Scores below 50 suggest further professional assessment. Your preferences determine the options you explore.</p><div class="button-row">${btn(`Explore trusted support ${icon('arrow')}`,'go-support','primary')}${btn('Check in again','restart-checkin','outline')}</div><div class="info-divider"></div><div class="card-top"><span class="muted-small">${state.consent.history?'Session history is enabled. No data survives a reload.':'History is off. This result is temporary in this browser session.'}</span><button class="text-link" data-action="go-privacy">Your privacy choices ${icon('arrow')}</button></div>${state.history.length?`<div class="history-list">${state.history.map((x,i)=>`<span class="history-point">Check-in ${i+1}<strong>${x.score}/100</strong></span>`).join('')}</div>`:''}</section><aside class="card info-card"><div class="round-icon">${icon('compass')}</div><h3>One step is enough.</h3><p>You can explore self-help, speak with primary care, or consider specialist support. SILA does not decide your clinical needs.</p><div class="info-divider"></div><p>A check-in is never required to access urgent support.</p><button class="text-link" data-action="urgent">I need help now ${icon('arrow')}</button></aside></div><div class="assessment-footer">World Health Organization (2024), WHO-5 Well-Being Index · CC BY-NC-SA 3.0 IGO. <a href="https://www.who.int/publications/m/item/WHO-UCN-MSD-MHE-2024.01" target="_blank" rel="noopener noreferrer">Instrument and interpretation</a>. No diagnosis, clinical recommendation engine, or live care integration.</div>`;
}

function supportPage(){
  const filtered=services.filter(s=>(state.preferences.type==='all'||s.type===state.preferences.type)&&(state.preferences.format==='any'||s.format==='both'||s.format===state.preferences.format)&&s.languages.includes(state.preferences.language));
  return `${heading('Find your next step.','Trusted options, guided by your preferences. Always your choice.','SUPPORT THAT FITS YOUR LIFE')}
  <div class="card filter-bar"><div class="field"><label for="service-type">SUPPORT TYPE</label><select id="service-type" data-filter="type"><option value="all" ${state.preferences.type==='all'?'selected':''}>All support options</option><option value="primary" ${state.preferences.type==='primary'?'selected':''}>Primary care</option><option value="specialist" ${state.preferences.type==='specialist'?'selected':''}>Mental health services</option><option value="self-help" ${state.preferences.type==='self-help'?'selected':''}>Self-help</option></select></div><div class="field"><label for="service-language">PREFERRED LANGUAGE</label><select id="service-language" data-filter="language"><option ${state.preferences.language==='English'?'selected':''}>English</option><option ${state.preferences.language==='Arabic'?'selected':''}>Arabic</option></select></div><div class="field"><label for="service-format">HOW YOU CONNECT</label><select id="service-format" data-filter="format"><option value="any" ${state.preferences.format==='any'?'selected':''}>Remote or in person</option><option value="remote" ${state.preferences.format==='remote'?'selected':''}>Remote</option><option value="in-person" ${state.preferences.format==='in-person'?'selected':''}>In person</option></select></div></div>
  <div class="section-heading"><h2>${filtered.length} support ${filtered.length===1?'option':'options'} to explore</h2><span class="label">Preference matching · no clinical ranking</span></div><div class="service-grid">${filtered.map(s=>`<article class="card service-card"><div class="card-top"><div class="service-icon">${icon(s.icon)}</div><span class="badge neutral">Official resource</span></div><h2>${s.name}</h2><div class="service-type">${s.label}</div><p>${s.description}</p><div class="service-tags">${s.tags.map(t=>`<span>${t}</span>`).join('')}<span>${state.preferences.language}</span></div><div class="match-reason">Shown for your selected ${state.preferences.language.toLowerCase()}${state.preferences.format!=='any'?` · ${state.preferences.format==='remote'?'remote':'in-person'}`:''} preference. Confirm service access directly.</div><div class="service-actions">${s.recipient?`<button class="btn btn-primary btn-small" data-action="open-handoff" data-service="${s.id}">Try a handoff ${icon('arrow')}</button>`:''}<a class="text-link" href="${s.url}" target="_blank" rel="noopener noreferrer">${s.recipient?'Official site':'Explore WHO guide'} ${icon('external')}</a></div></article>`).join('')}</div><div class="directory-note">Directory checked 20 October 2026 using official <a href="https://sakina.seha.ae" target="_blank" rel="noopener noreferrer">Sakina</a>, <a href="https://www.seha.ae" target="_blank" rel="noopener noreferrer">SEHA</a> and <a href="https://www.who.int/publications/i/item/9789240003927" target="_blank" rel="noopener noreferrer">WHO</a> sources. Confirm eligibility, language, current availability, insurance and cost directly. No appointment or response is guaranteed. These services do not receive information from SILA. Arabic is an access preference; this interface is English only.</div><div style="margin-top:20px">${notice('<strong>A person makes the care decision.</strong> These options match the preferences you selected. A wellbeing score never determines your access to a service. A handoff in this prototype is a simulation.')}</div>`;
}

function referralTimeline(referral){
  const events=referral.uiEvents||[{title:'You approved a handoff',description:'Only the information you selected was included.',time:'Just now'}];
  return `<div class="timeline">${events.map(e=>`<div class="timeline-item"><span class="timeline-marker">${icon(e.type==='withdraw'?'lock':e.type==='decline'?'info':'tick')}</span><div><h3>${esc(e.title)}</h3><p>${esc(e.description)}</p><small>${esc(e.time)} · ${e.type==='sent'?'Your consent':'Simulation'}</small></div></div>`).join('')}${referral.status==='sent'?`<div class="timeline-item"><span class="timeline-marker">${icon('clock')}</span><div><h3>Waiting for a human response</h3><p>The care-team simulation can accept, decline, or suggest a reroute.</p><small>No real service has been contacted.</small></div></div>`:''}</div>`;
}
function approvedData(referral){
  if(referral.status==='withdrawn')return `<div class="receipt-data"><h3>${icon('lock')} Approved content is unavailable</h3><p>You withdrew sharing. This demo hides the handoff content from the care-team view. Prior viewing cannot be undone.</p></div>`;
  const d=referral.payload;
  return `<div class="receipt-data"><h3>${icon('shield')} Information you approved for this recipient</h3>${Object.hasOwn(d,'score')?`<p>WHO-5 score: ${esc(typeof d.score==='object'?d.score.score:d.score)} / 100</p>`:''}${Object.hasOwn(d,'needs')?`<p>Access preferences: ${esc(Array.isArray(d.needs)?d.needs.join(' · '):typeof d.needs==='object'?Object.values(d.needs).join(' · '):d.needs)}</p>`:''}${Object.hasOwn(d,'physicalContext')?`<p>Physical health context: ${esc(Array.isArray(d.physicalContext)?d.physicalContext.join(' · '):d.physicalContext)}</p>`:''}<p style="margin-top:6px;font-size:8px">No name, contact information or questionnaire answers.</p></div>`;
}
function journeyPage(){
  const r=activeReferral();
  if(!r)return `${heading('Your care journey.','Every connection deserves a clear next step.','FROM SIGNAL TO HUMAN SUPPORT')}<section class="card empty-state"><div class="round-icon">${icon('journey')}</div><h2>Start with a step that feels right.</h2><p>When you choose support and approve a simulated handoff, you’ll see a receipt here. No information is sent without your choice.</p>${btn(`Explore support ${icon('arrow')}`,'go-support','primary')}</section>`;
  const canWithdraw=r.status!=='withdrawn';
  return `${heading('Your next step is visible.','A clear receipt, from your approval to a human response.','YOUR CARE JOURNEY')}
  ${state.referrals.length>1?`<div class="section-tabs" style="margin-bottom:20px">${state.referrals.map((x,i)=>`<button class="chip ${x.id===r.id?'active':''}" data-action="select-referral" data-id="${x.id}">Handoff ${i+1} · ${esc(x.serviceName)}</button>`).join('')}</div>`:''}
  <div class="journey-layout"><section class="card"><div class="referral-header"><div><span class="ref-code">${r.id} · DEMO RECEIPT</span><h2>${esc(r.serviceName)}</h2><p>${esc(r.recipient)}</p></div><span class="badge ${statusClass(r.status)}">${statusLabel(r.status)}</span></div>${r.status==='declined'?'<div class="declined-banner">The simulated service cannot take this handoff. You can choose another option. A declined handoff never means you are ineligible for care.</div>':''}${referralTimeline(r)}${approvedData(r)}<div class="button-row">${r.status==='declined'||r.status==='rerouted'?btn(`Choose another option ${icon('arrow')}`,'go-support','primary'):btn(`Open care-team simulation ${icon('arrow')}`,'go-care-team','outline')}${canWithdraw?btn('Withdraw sharing','withdraw-referral','soft',`data-id="${r.id}"`):''}${canWithdraw?btn(`${icon('download')} Download demo receipt`,'download-receipt','outline',`data-id="${r.id}"`):''}</div></section><aside><div class="card info-card"><div class="round-icon">${icon('team')}</div><h3>The next decision is human.</h3><p>In a real care pathway, a licensed professional would review your needs, confirm suitability, and arrange a next step.</p><div class="info-divider"></div><p>This prototype shows a simulated acceptance, decline, reroute, and completed contact. It does not book an appointment or contact a provider.</p><button class="text-link" data-action="urgent">Need help sooner? ${icon('arrow')}</button></div></aside></div>`;
}

function privacyPage(){
  const options=[['history','Keep a check-in history in this session','Allow temporary score history while this page remains open. Turning this off clears that history.'],['score','Allow a WHO-5 score in a future handoff','You still review and approve each recipient and each handoff. Individual answers are never included.'],['access','Allow practical access preferences','Language and remote / in-person preferences can help a person plan an appropriate next step.'],['physical','Allow optional physical health context','Only the predefined context you select below. No records, medication lists, or diagnoses are collected.']];
  return `${heading('Your information. Your choice.','Consent should be clear, specific, and easy to change.','PRIVACY & CONSENT')}
  <div class="consent-layout"><div><section class="card consent-card">${options.map(([id,title,text])=>`<div class="consent-row"><div><h3>${title}</h3><p>${text}</p></div><button class="switch" role="switch" aria-checked="${state.consent[id]}" aria-label="${title}" data-action="toggle-consent" data-key="${id}"></button></div>${id==='physical'&&state.consent.physical?`<div class="physical-choices"><p>Optional context to discuss with a professional:</p><div class="section-tabs">${['Sleep concerns','Long-term condition','Persistent pain','Prefer to discuss privately'].map(x=>`<button class="chip ${state.physical.includes(x)?'active':''}" data-action="physical-choice" data-value="${x}">${x}</button>`).join('')}</div></div>`:''}`).join('')}</section><div class="privacy-actions">${btn(`${icon('trash')} Clear all demo data`,'clear-data','outline')}<span class="muted-small">All entries are temporary. Reloading also resets the demo.</span></div><div style="margin-top:20px">${notice('<strong>Revoking consent takes effect here immediately.</strong> Existing handoffs that included the revoked category are withdrawn and their approved content is hidden from the care-team view. This cannot undo information already viewed.')}</div></div><aside class="card privacy-side"><div class="round-icon">${icon('shield')}</div><h3 style="margin-top:17px">Privacy is part<br>of the pathway.</h3><ul><li>${icon('tick')}<span>No microphone, camera, wearable or background monitoring.</span></li><li>${icon('tick')}<span>No name, email, phone or employer information collected.</span></li><li>${icon('tick')}<span>No health data is sent to an analytics service or healthcare provider.</span></li><li>${icon('tick')}<span>No browser storage. Data lives only in this open session.</span></li></ul><div class="info-divider"></div><p class="muted-small">This is a same-browser demonstration, without identity verification or production access controls. A deployed clinical service would need security, legal and clinical review.</p></aside></div>`;
}

function careTeamPage(){
  const r=activeReferral();
  return `${heading('A human at the next step.','See how a care team can close the loop, one handoff at a time.','CARE-TEAM WORKSPACE')}
  <div class="simulation-ribbon">${icon('info')} <span><strong>Simulation workspace.</strong> Same browser, synthetic participant. No provider receives this information. No clinical account or live booking.</span></div>
  <section class="card"><div class="card-top"><div><h2 class="trend-title">Handoff inbox</h2><span class="trend-sub">Only the participant-approved information is shown</span></div><span class="badge neutral">${state.referrals.length} demo ${state.referrals.length===1?'handoff':'handoffs'}</span></div>${state.referrals.length?`<div class="table-wrap"><table class="queue-table"><thead><tr><th>PARTICIPANT</th><th>RECIPIENT</th><th>STATUS</th><th></th></tr></thead><tbody>${state.referrals.map(x=>`<tr><td><strong>Demo participant</strong><small>${x.id} · Synthetic adult 18+</small></td><td>${esc(x.serviceName)}</td><td><span class="badge ${statusClass(x.status)}">${statusLabel(x.status)}</span></td><td><button class="text-link" data-action="select-referral" data-id="${x.id}">${r?.id===x.id?'Selected':'Review'} ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state" style="padding:35px 15px"><div class="round-icon">${icon('mail')}</div><h2 style="font-size:24px">No handoffs to review.</h2><p>Choose a support option and approve a limited handoff to try the care-team workflow.</p>${btn('Explore support','go-support','outline')}</div>`}</section>
  ${r?`<section class="card clinician-details"><div class="card-top"><div class="card-kicker">${icon('eye')} REVIEW · ${r.id}</div><span class="badge neutral">Synthetic participant</span></div><h2 class="trend-title" style="margin:0 0 17px">${esc(r.recipient)}</h2>${approvedData(r)}${r.status!=='withdrawn'?`<div class="care-context"><h3>Human review comes first.</h3><p>No diagnosis or clinical eligibility decision has been generated. The service would confirm suitability, urgency, availability and next steps directly.</p></div><div class="clinician-actions">${r.status==='sent'?`${btn(`${icon('tick')} Accept handoff`,'provider-accept','primary',`data-id="${r.id}"`)}${btn('Decline · capacity unavailable','provider-decline','outline',`data-id="${r.id}"`)}${btn('Suggest a reroute','provider-reroute','soft',`data-id="${r.id}"`)}`:''}${r.status==='accepted'?`${btn(`${icon('tick')} Confirm contact completed`,'provider-complete','primary',`data-id="${r.id}"`)}${btn('Suggest a reroute','provider-reroute','outline',`data-id="${r.id}"`)}`:''}${r.status==='rerouted'?'<p class="reroute-instruction">This handoff is closed to further review. Choose a different service and approve a new handoff; no information has been forwarded.</p>':''}${r.status==='completed'?'<span class="badge success">Human contact recorded · simulated</span>':''}${r.status==='declined'?btn('Suggest a reroute','provider-reroute','outline',`data-id="${r.id}"`):''}</div>`:''}<p class="muted-small" style="margin:19px 0 0">Actions update the participant’s receipt immediately in this demonstration. No real clinician, provider or appointment is involved.</p></section>`:''}`;
}

function outcomesPage(){
  const summary=summarizeOutcomes(state.referrals);const total=summary.total;const ack=summary.acknowledged;const completed=summary.completed;
  return `${heading('See whether care connected.','Measure the connection, the waiting, and the gaps that need a human response.','OUTCOMES & SAFETY')}
  ${notice('<strong>Demonstration metrics, not patient outcomes.</strong> Session counts come from your simulated handoffs. The chart below is a synthetic fixture; no pilot results or clinical effectiveness are claimed.')}
  <div class="kpi-grid"><div class="card kpi"><span>SIMULATED HANDOFFS</span><div class="kpi-value">${total}</div><p>Created in this session</p></div><div class="card kpi"><span>HUMAN RESPONSE RECORDED</span><div class="kpi-value">${total?Math.round(ack/total*100):0}<small>%</small></div><p>${ack} of ${total} simulated handoffs</p></div><div class="card kpi"><span>CONTACT COMPLETED</span><div class="kpi-value">${completed}</div><p>Simulated confirmation only</p></div><div class="card kpi"><span>WAITING TIME</span><div class="kpi-value">—</div><p>Requires a prospective pilot</p></div></div>
  <div class="outcomes-grid"><section class="card"><div class="card-top"><div><div class="outcome-fixture-label">SYNTHETIC FIXTURE · 100 JOURNEYS</div><h2 class="trend-title">Where a care pathway can lose connection</h2></div></div><div class="bar-chart"><div class="bar-group"><div class="bar" style="height:100%" data-value="100"></div></div><div class="bar-group"><div class="bar" style="height:82%" data-value="82"></div></div><div class="bar-group"><div class="bar" style="height:66%" data-value="66"></div></div><div class="bar-group"><div class="bar" style="height:54%" data-value="54"></div></div></div><div style="display:flex;justify-content:space-around"><span class="bar-label">Approved</span><span class="bar-label">Acknowledged</span><span class="bar-label">Accepted</span><span class="bar-label">Contacted</span></div><p class="muted-small" style="margin-bottom:0">Illustrative numbers explain the measurement model. They are not observed performance, targets or evidence of benefit.</p></section><section class="card"><h2 class="trend-title">Fairness needs enough context.</h2><p class="muted-small">Only consented aggregate groups would be compared. Small groups stay suppressed.</p>${['Age','Gender','Nationality','Language','Geography'].map(x=>`<div class="fairness-row"><span>${x}</span><span>Suppressed · group size &lt; 10</span></div>`).join('')}<p class="muted-small" style="font-size:8px">No demographic data is collected in this demo. Suppression is illustrative, not a guarantee of anonymity.</p></section></div>
  <section class="card" style="margin-top:20px"><h2 class="trend-title">What a clinically governed pilot would monitor</h2><div class="metric-list"><div class="metric-item"><span>Follow-up within the intended timeframe</span><small>2 working days acknowledgement · 7 days first contact, proposed</small></div><div class="metric-item"><span>Symptom and functioning change</span><small>Consented WHO-5 follow-up + person-reported functioning</small></div><div class="metric-item"><span>Crisis-response completion and adverse events</span><small>Human review, near misses, and safety follow-up required</small></div><div class="metric-item"><span>Fairness across sufficiently sized groups</span><small>Age, gender, nationality, language and geography</small></div></div></section>`;
}

function openModal(type){
  priorFocus=document.activeElement;state.modal=type;document.body.style.overflow='hidden';
  if(type==='urgent')renderUrgentModal();
  if(type==='handoff')renderHandoffModal();
  setTimeout(()=>modalRoot.querySelector('button')?.focus(),0);
}
function closeModal(){modalRoot.innerHTML='';state.modal=null;document.body.style.overflow='';priorFocus?.focus();}
function modalShell(content,cls=''){modalRoot.innerHTML=`<div class="modal-backdrop"><section class="modal ${cls}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="modal-close" aria-label="Close dialog" data-action="close-modal">${icon('close')}</button>${content}</section></div>`;}
function renderUrgentModal(){
  modalShell(`<div class="round-icon">${icon('life')}</div><div class="eyebrow" style="margin-top:20px">IMMEDIATE HUMAN SUPPORT</div><h2 id="modal-title">You deserve help right now.</h2><p>You do not need to finish a check-in or share any information here to seek urgent support.</p><div class="emergency-card"><h3>If you or someone else is in immediate danger</h3><p>Call the UAE ambulance service on <strong>998</strong>, or go to the nearest emergency department. If you can, ask a trusted person to stay with you.</p><a class="btn btn-danger" href="tel:998">${icon('phone')} Call 998 · UAE ambulance</a></div><div class="urgent-step"><span>1</span><div><strong>Connect with someone you trust.</strong><p>Tell them you need support now. Move to a safer place if you can do so safely.</p></div></div><div class="urgent-step"><span>2</span><div><strong>Speak with a licensed professional.</strong><p>For support that is not an immediate emergency, explore <a href="https://sakina.seha.ae" target="_blank" rel="noopener noreferrer" style="text-decoration:underline">Sakina’s official services</a> and confirm current availability directly.</p></div></div><label class="urgent-self-disclosure"><input type="checkbox" id="urgent-disclosure" ${state.urgentSelfDisclosure?'checked':''}><span>I am concerned about my immediate safety or thoughts of suicide or self-harm. ${state.urgentSelfDisclosure?'<strong>Please use the immediate emergency options above. No message is being sent.</strong>':'This optional disclosure stays in this session.'}</span></label>${notice('<strong>SILA cannot contact emergency services or transfer you to a live professional.</strong> This page is not monitored. Use the call button or seek in-person emergency care.','warning')}<p class="muted-small" style="font-size:8px;margin-bottom:0">UAE official emergency guidance: <a href="https://u.ae/en/information-and-services/justice-safety-and-the-law/handling-emergencies" target="_blank" rel="noopener noreferrer" style="text-decoration:underline">UAE Government · Handling emergencies</a>. Outside the UAE, call your local emergency number.</p>`,'urgent-modal');
}
function renderHandoffModal(){
  const s=services.find(x=>x.id===state.selectedService)||services[1];
  const canSend=Object.values(state.share).some(Boolean);
  modalShell(`<div class="round-icon">${icon('shield')}</div><div class="eyebrow" style="margin-top:18px">YOUR PERMISSION COMES FIRST</div><h2 id="modal-title">Choose what travels<br>with your handoff.</h2><p>Review the recipient and select the information they may see. This creates a simulated receipt only.</p><div class="field"><label for="handoff-recipient">RECIPIENT · SIMULATION</label><select id="handoff-recipient">${services.filter(x=>x.recipient).map(x=>`<option value="${x.id}" ${s.id===x.id?'selected':''}>${x.recipient}</option>`).join('')}</select></div><label class="share-option"><input type="checkbox" data-share="score" ${state.share.score?'checked':''} ${!state.assessment?'disabled':''}><span><strong>WHO-5 wellbeing score</strong>${state.assessment?`${state.assessment.score} / 100 · current check-in only`:'Complete a check-in first. No illustrative score is shared.'}</span></label><label class="share-option"><input type="checkbox" data-share="access" ${state.share.access?'checked':''}><span><strong>Practical access preferences</strong>${state.preferences.language} · ${state.preferences.format==='any'?'Remote or in person':state.preferences.format==='remote'?'Remote':'In person'}</span></label><label class="share-option"><input type="checkbox" data-share="physical" ${state.share.physical?'checked':''} ${!state.physical.length?'disabled':''}><span><strong>Optional physical health context</strong>${state.physical.length?esc(state.physical.join(' · ')):'Select predefined context in Privacy & consent first.'}</span></label>${notice('<strong>No personal identifiers or individual answers.</strong> A care professional would make the final decision. You can withdraw sharing from your care journey.')}<div class="modal-actions"><span class="muted-small">${canSend?'By continuing, you approve these selected fields for this recipient in this demo.':'Choose at least one item. Everything is optional until you approve.'}</span><button class="btn btn-primary" data-action="send-handoff" ${!canSend?'disabled':''}>Approve demo handoff ${icon('arrow')}</button></div>`);
}

function toast(text){clearTimeout(toastTimer);const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),3800);}
function applyReferralAction(id,action){
  const index=state.referrals.findIndex(r=>r.id===id);if(index<0)return;
  const old=state.referrals[index];if(old.status==='withdrawn')return;
  const eventMap={accept:{status:'accepted',title:'The care team accepted your handoff',description:'A human response is recorded. No real appointment has been arranged.'},decline:{status:'declined',title:'The care team declined · capacity unavailable',description:'You can explore another option or ask for a reroute. No eligibility decision was made.'},reroute:{status:'rerouted',title:'A human suggested another route',description:'Choose a new service and approve a new handoff. Your information is never forwarded automatically.'},complete:{status:'completed',title:'Human contact confirmed',description:'The simulated care team recorded first contact. This is a demonstration, not evidence of delivered care.'},withdraw:{status:'withdrawn',title:'You withdrew sharing',description:'The approved content is hidden from the care-team view. Information already viewed cannot be recalled.'}};
  const e=eventMap[action];if(!e)return;
  const updated=transitionReferral(old,action,new Date().toISOString());
  state.referrals[index]={...updated,uiEvents:[...(old.uiEvents||[]),{...e,type:action,time:'Just now'}]};
  state.selectedReferral=id;render();toast(action==='withdraw'?'Sharing withdrawn. The care-team content is now hidden.':`${e.title} · simulated`);
}
function sendHandoff(){
  const s=services.find(x=>x.id===state.selectedService);if(!s?.recipient||!Object.values(state.share).some(Boolean))return;
  const context={score:state.assessment?.score,needs:[state.preferences.language,state.preferences.format==='any'?'Remote or in person':state.preferences.format==='remote'?'Remote':'In person'],physicalContext:[...state.physical]};
  const consent={score:state.share.score&&Boolean(state.assessment),needs:state.share.access,access:state.share.access,physicalContext:state.share.physical,physical:state.share.physical};
  const payload=buildHandoff(context,consent);
  const r={id:`SILA-${String(state.referrals.length+1).padStart(3,'0')}`,status:'sent',serviceName:s.name,recipient:s.recipient,payload,approvedKeys:{...state.share},createdAt:new Date().toISOString(),events:[],uiEvents:[{type:'sent',title:'You approved a handoff',description:`You selected ${s.name} and approved ${Object.values(state.share).filter(Boolean).length} information ${Object.values(state.share).filter(Boolean).length===1?'category':'categories'}. No provider has been contacted.`,time:'Just now'}]};
  state.referrals.push(r);state.selectedReferral=r.id;
  Object.entries(state.share).forEach(([key,val])=>{if(val)state.consent[key]=true;});
  closeModal();go('journey');toast('Your simulated handoff receipt is ready.');
}

document.addEventListener('click',event=>{
  const target=event.target.closest('[data-action]');if(!target)return;
  const action=target.dataset.action;
  if(action.startsWith('go-')){go(action.slice(3));return;}
  if(action==='urgent'){openModal('urgent');return;}
  if(action==='close-modal'){closeModal();return;}
  if(action==='start-checkin'){if(state.step===5)state.step=0;go('check-in');return;}
  if(action==='restart-checkin'){state.step=0;state.answers=Array(5).fill(null);state.assessment=null;render();return;}
  if(action==='answer'){state.answers[state.step]=Number(target.dataset.value);render();return;}
  if(action==='previous-question'){if(state.step>0)state.step--;render();return;}
  if(action==='next-question'){
    if(state.answers[state.step]===null)return;
    if(state.step<4){state.step++;render();return;}
    state.assessment=scoreWho5(state.answers);state.step=5;if(state.consent.history)state.history.push({...state.assessment});render();main.focus();return;
  }
  if(action==='open-handoff'){state.selectedService=target.dataset.service;state.share={score:state.consent.score&&Boolean(state.assessment),access:state.consent.access,physical:state.consent.physical&&Boolean(state.physical.length)};openModal('handoff');return;}
  if(action==='send-handoff'){sendHandoff();return;}
  if(action==='download-receipt'){
    const r=state.referrals.find(x=>x.id===target.dataset.id);if(!r||r.status==='withdrawn')return;
    const receipt={demo:true,notice:'Synthetic demonstration only. No service was contacted. This is a user-controlled summary, not a validated FHIR record or evidence of care.',receipt:r.id,recipient:r.recipient,status:r.status,approvedInformation:r.payload,timeline:r.uiEvents,createdAt:r.createdAt};
    const url=URL.createObjectURL(new Blob([JSON.stringify(receipt,null,2)],{type:'application/json'}));
    const link=document.createElement('a');link.href=url;link.download=`${r.id}-demo-receipt.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your demo receipt has been downloaded.');return;
  }
  if(action==='select-referral'){state.selectedReferral=target.dataset.id;render();return;}
  if(action==='withdraw-referral'){applyReferralAction(target.dataset.id,'withdraw');return;}
  if(action.startsWith('provider-')){applyReferralAction(target.dataset.id,action.slice(9));return;}
  if(action==='toggle-consent'){
    const key=target.dataset.key;state.consent[key]=!state.consent[key];
    if(!state.consent[key]){
      if(key==='history')state.history=[];
      state.referrals.filter(r=>r.status!=='withdrawn'&&r.approvedKeys[key]).forEach(r=>applyReferralAction(r.id,'withdraw'));
    }
    render();toast(state.consent[key]?'Your preference is enabled for this session.':'Consent revoked for this category.');return;
  }
  if(action==='physical-choice'){const value=target.dataset.value;state.physical=state.physical.includes(value)?state.physical.filter(x=>x!==value):[...state.physical,value];render();return;}
  if(action==='clear-data'){state.assessment=null;state.history=[];state.referrals=[];state.selectedReferral=null;state.answers=Array(5).fill(null);state.step=0;state.physical=[];state.urgentSelfDisclosure=false;state.consent={history:false,score:false,access:false,physical:false};state.preferences={type:'all',language:'English',format:'any'};render();toast('All temporary demo data has been cleared.');return;}
});
document.addEventListener('change',event=>{
  const el=event.target;
  if(el.dataset.filter){state.preferences[el.dataset.filter]=el.value;render();}
  if(el.dataset.share){state.share[el.dataset.share]=el.checked;renderHandoffModal();modalRoot.querySelector(`[data-share="${el.dataset.share}"]`)?.focus();}
  if(el.id==='handoff-recipient')state.selectedService=el.value;
  if(el.id==='urgent-disclosure'){state.urgentSelfDisclosure=el.checked;renderUrgentModal();modalRoot.querySelector('#urgent-disclosure')?.focus();}
});
modalRoot.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();});
document.addEventListener('keydown',event=>{
  if(!state.modal)return;
  if(event.key==='Escape'){closeModal();return;}
  if(event.key==='Tab'){
    const focusable=[...modalRoot.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled)')];
    const first=focusable[0],last=focusable[focusable.length-1];
    if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}
  }
});
navigate(location.hash.slice(1)||'overview');
